arguments.new_string:
# align "=" has been handled
if align == '<':
    # Left-aligned: consume up to the next space character
    s = '%s%s*' % (s, fill)
elif align == '>':
    s = '%s*%s' % (fill, s)
elif align == '^':
    # Center-aligned: consume up to the next space character after value
    s = '%s*%s%s*' % (fill, s, fill)

